WITH metrics AS (SELECT id, balance, status, SUM(balance) OVER (PARTITION BY account_type ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_balance, COUNT(balance) OVER (PARTITION BY account_type ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_count_balance, MIN(balance) OVER (PARTITION BY account_type ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_balance, AVG(balance) OVER (PARTITION BY account_type ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_balance FROM accounts WHERE customer_id = 20) SELECT CASE WHEN running_sum_balance >= 345000 THEN 'LARGE' ELSE 'SMALL' END AS running_sum_balance_tier, status, COUNT(*) FILTER (WHERE status = 'FROZEN') AS frozen_rows, APPROX_PERCENTILE(running_count_balance, ARRAY(0.25, 0.5, 0.75)) AS running_count_balance_quartiles, ROUND(SUM(running_avg_balance) / NULLIF(COUNT(CASE WHEN status = 'FROZEN' THEN 1 END), 0), 2) AS running_avg_balance_per_frozen FROM metrics GROUP BY CASE WHEN running_sum_balance >= 345000 THEN 'LARGE' ELSE 'SMALL' END, status ORDER BY frozen_rows DESC;
